<?php declare(strict_types=1); require __DIR__.'/admin-empresa-action-common.php'; admin_empresa_post(); [$app,$session]=admin_empresa_context(); try{$supplierId=filter_var($_POST['fornecedor_so_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!is_int($supplierId))throw new InvalidArgumentException('Fornecedor inválido.');$companyId=filter_var($_POST['empresa_id']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!is_int($companyId)){$supplier=$app->soSupplierService()->find($supplierId);$company=$supplier?->cnpj()!==null?$app->companyAdmin()->findByDocument($supplier->cnpj()):null;$companyId=(int)($company['id']??0);}if($companyId<=0)throw new InvalidArgumentException('Empresa correspondente não encontrada.');$app->companyAdmin()->link($companyId,$supplierId,$app->soSupplierService());$session->flash('success','Fornecedor vinculado à empresa.');}catch(InvalidArgumentException $e){$session->flash('danger',$e->getMessage());}catch(Throwable $e){error_log('Company SO link failed: '.get_class($e));$session->flash('danger','Não foi possível vincular o fornecedor.');}admin_empresa_redirect($app);
